mapper.select:
/* 랜덤 슬라이드용 매칭 리스트 조회 */ SELECT * FROM ( SELECT m.seqMember AS seqMember, m.nickname AS nickname, m.pic AS pic, m.gender AS gender, TRUNC(MONTHS_BETWEEN(SYSDATE, m.birth) / 12) AS age, p.mbti AS mbti, p.smoking AS smoking, p.drinking AS drinking,
-- 8가지 성향 일치 개수 계산 (matchCount) ( (CASE WHEN p.mbti = my.mbti THEN 1 ELSE 0 END) + (CASE WHEN p.smoking = my.smoking THEN 1 ELSE 0 END) + (CASE WHEN p.drinking = my.drinking THEN 1 ELSE 0 END) + (CASE WHEN p.travelType = my.travelType THEN 1 ELSE 0 END) + (CASE WHEN p.stepCount = my.stepCount THEN 1 ELSE 0 END) + (CASE WHEN EXISTS (SELECT 1 FROM profile_stay ps1 JOIN profile_stay ps2 ON ps1.seqStay = ps2.seqStay WHERE ps1.seqMember = m.seqMember AND ps2.seqMember = #{loginSeq}) THEN 1 ELSE 0 END) + (CASE WHEN EXISTS (SELECT 1 FROM profile_language pl1 JOIN profile_language pl2 ON pl1.seqLanguage = pl2.seqLanguage WHERE pl1.seqMember = m.seqMember AND pl2.seqMember = #{loginSeq}) THEN 1 ELSE 0 END) + (CASE WHEN EXISTS (SELECT 1 FROM profile_age_group pag1 JOIN profile_age_group pag2 ON pag1.seqAgeGroup = pag2.seqAgeGroup WHERE pag1.seqMember = m.seqMember AND pag2.seqMember = #{loginSeq}) THEN 1 ELSE 0 END) ) AS matchCount
FROM member m JOIN profile p ON m.seqMember = p.seqMember
-- 로그인한 유저 정보와 비교하기 위한 CROSS JOIN CROSS JOIN (SELECT * FROM profile WHERE seqMember = #{loginSeq}) my
WHERE m.status = 0 -- 🚨 임시로 주석 처리: DB의 type 데이터가 0이 아닐까봐 잠시 끕니다. -- AND m.type = 0 AND m.seqMember != #{loginSeq} -- 본인 제외
-- 동적 필터 조건 AND p.mbti = #{mbti} AND p.smoking = #{smoking} AND p.drinking = #{drinking} AND p.travelType = #{travelType} AND p.stepCount = #{stepCount}
-- 1단계: 먼저 랜덤으로 섞습니다. ORDER BY DBMS_RANDOM.VALUE
) a -- 🚨 오라클의 깐깐함을 피하기 위해 'a'라는 별칭을 붙여주었습니다.
-- 2단계: 섞인 결과물 중 상단 10명만 가져옵니다. WHERE ROWNUM <= 10
